function admClick(e){
 const b=e.target.closest('[data-adm]');if(!b)return false;const a=b.dataset.adm,i=Number(b.dataset.i),j=Number(b.dataset.j);
 const mv=(arr,x,y)=>{if(y<0||y>=arr.length)return;[arr[x],arr[y]]=[arr[y],arr[x]]};
 const done=(chrome)=>{admSave(chrome);admRerender()};
 switch(a){
  case 'logout':sess.del('admin');location.hash='#/';return true;
  case 'newtour':{const t={id:newId('tour-'),title:'Новая экскурсия',cat:'sea',district:'gagra',pin:'gagra',loc:'Гагра',hours:4,dur:'4 часа',price:2000,kid:1000,rating:5,reviews:0,popular:false,hidden:true,short:'Короткое описание для карточки.',photos:[],scenes:[['sea',0],['mountains',1],['garden',2]],format:'Групповая, минивэн',group:'до 12 человек',lang:'Русский',times:['09:00'],about:['Расскажите, о чём экскурсия.'],program:[['09:00','Выезд','Сбор у отелей.']],incl:['Транспорт и гид'],excl:['Обед'],meet:'Сбор у вашего отеля.',notes:[]};C.tours.unshift(t);markNewTour(t.id);saveContent();adminNavigationPermit=true;location.hash='#/admin/tours/'+t.id;toast('Черновик экскурсии создан. Заполните поля и нажмите «Сохранить».');return true}
  case 'dup':{const c=clone(C.tours[i]);c.id=newId(c.id.replace(/-\w+$/,'')+'-');c.title+=' (копия)';c.hidden=true;c.popular=false;markNewTour(c.id);C.tours.splice(i+1,0,c);saveContent();adminNavigationPermit=true;location.hash='#/admin/tours/'+c.id;return true}
  case 'deltour':if(confirm('Удалить экскурсию «'+C.tours[i].title+'»?')){C.tours.splice(i,1);saveContent();if(parseHash().parts[2]){adminNavigationPermit=true;location.hash='#/admin/tours';}else admRerender();toast('Удалено')}return true;
  case 'up':mv(C.tours,i,i-1);done();return true;
  case 'down':mv(C.tours,i,i+1);done();return true;
  case 'ph-left':mv(C.tours[i].photos=C.tours[i].photos.filter(Boolean),j,j-1);done();return true;
  case 'ph-right':mv(C.tours[i].photos=C.tours[i].photos.filter(Boolean),j,j+1);done();return true;
  case 'ph-del':{const ph=C.tours[i].photos.filter(Boolean);const [x]=ph.splice(j,1);C.tours[i].photos=ph;if(x&&x.startsWith('img:'))idb.del(x.slice(4));done();return true}
  case 'pr-add':(C.tours[i].program=C.tours[i].program||[]).push(['','','']);done();return true;
  case 'pr-del':C.tours[i].program.splice(j,1);done();return true;
  case 'pr-up':mv(C.tours[i].program,j,j-1);done();return true;
  case 'newya':C.reviews.unshift({id:newId('y'),src:'ya',n:'',c:'',d:monthNow(),r:5,x:'',t:''});saveContent();if(parseHash().parts[1]!=='reviews')location.hash='#/admin/reviews';else admRerender();setTimeout(()=>{const f=$('[data-k="reviews.0.n"]');if(f)f.focus()},60);return true;
  case 'deldemo':if(confirm('Удалить все демонстрационные отзывы?')){C.reviews=C.reviews.filter(r=>r.src!=='demo');done()}return true;
  case 'rv-up':mv(C.reviews,j,j-1);done();return true;
  case 'rv-del':if(confirm('Удалить отзыв?')){C.reviews.splice(j,1);done()}return true;
  case 'newstory':C.stories.unshift({id:newId('s'),t:'',a:'',x:'',photo:'',scene:['mountains',hash(Date.now())%3]});done();setTimeout(()=>{const f=$('[data-k="stories.0.t"]');if(f)f.focus()},60);return true;
  case 'st-up':mv(C.stories,j,j-1);done();return true;
  case 'st-del':if(confirm('Удалить историю?')){C.stories.splice(j,1);done()}return true;
  case 'to-add':C.transfer.to.push({id:newId('to'),name:'',price:3000});done();return true;
  case 'to-del':C.transfer.to.splice(j,1);done();return true;
  case 'from-add':C.transfer.from.push({id:newId('fr'),name:'',add:0});done();return true;
  case 'from-del':if(C.transfer.from.length>1){C.transfer.from.splice(j,1);done()}return true;
  case 'export':exportAll();return true;
  case 'reset':if(confirm('Сбросить весь контент к исходному? Загруженные фото будут удалены.')){C=clone(DEFAULT);saveContent();idb.clear();renderChrome();admRerender();toast('Контент сброшен')}return true;
  case 'csv':{const b2=store.get('bookings',[]),t2=store.get('transfers',[]);const rows=[['Тип','Номер','Что','Дата','Время','Гости/класс','Имя','Телефон','Связь/цена']].concat(b2.map(x=>['Экскурсия',x.code,(tourById(x.tour)||{}).title||x.tour,x.date,x.time,x.adults+'+'+x.kids,x.name,x.phone,x.via]),t2.map(x=>['Трансфер',x.code,x.route,x.date,x.time,transferFormatLabel(x),x.name,x.phone,x.price]));
   download('apsua-zayavki.csv','﻿'+rows.map(r=>r.map(v=>'"'+String(v==null?'':v).replace(/"/g,'""')+'"').join(';')).join('\n'),'text/csv');return true}
 }
 return false;
}
let dlNs;
const dlReady=(window.claude&&typeof window.claude.use==='function')?window.claude.use('downloads').then(n=>{dlNs=n;return n}).catch(()=>null):Promise.resolve(null);
async function download(name,data,type){
 const ns=dlNs!==undefined?dlNs:await dlReady;
 if(ns){try{await ns.save({filename:name,data:new Blob([data],{type})});toast('Файл сохранён')}catch(e){if(e&&e.code!=='declined')toast('Не удалось сохранить файл')}return}
 const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([data],{type}));a.download=name;document.body.appendChild(a);a.click();setTimeout(()=>{URL.revokeObjectURL(a.href);a.remove()},500)}
function exportAll(){const used={};JSON.stringify(C).replace(/"img:([\w-]+)"/g,(m,k)=>{if(IMG[k])used[k]=IMG[k]});download('apsua-tour-kontent-'+iso(new Date())+'.json',JSON.stringify({app:'apsua-tour',v:1,content:C,images:used}),'application/json')}
function importAll(file){const r=new FileReader();r.onload=async()=>{try{const d=JSON.parse(r.result);if(!d||!d.content)throw 0;C=mergeDefaults(d.content,clone(DEFAULT));for(const [k,v] of Object.entries(d.images||{}))await idb.put(k,v);saveContent();renderChrome();admRerender();toast('Контент загружен')}catch(e){toast('Не удалось прочитать файл копии')}};r.readAsText(file)}
async function admFile(input){
 const files=[...(input.files||[])];if(!files.length)return;
 if(input.dataset.photo){const k=input.dataset.photo;const old=getPath(C,k);const v=await storePhoto(files[0],k==='site.logo'?600:1800);if(!v)return toast('Не удалось открыть изображение');if(old&&old.startsWith('img:'))idb.del(old.slice(4));setPath(C,k,v);admSave(k.startsWith('site.'));admRerender();return}
 if(input.dataset.tphoto!=null){const i=Number(input.dataset.tphoto);const t=C.tours[i];t.photos=(t.photos||[]).filter(Boolean);for(const f of files){const v=await storePhoto(f,1800);if(v)t.photos.push(v)}admSave();admRerender();toast('Фото добавлены');return}
 if(input.hasAttribute('data-import'))importAll(files[0]);
}
function admInput(e){
 const el=e.target;const k=el.dataset.k;if(!k)return;const t=el.dataset.t;if(el.checkValidity&&!el.checkValidity()){adminDirty=true;updateAdminSaveState();admStatus('Проверьте значение поля',true);return}
 let v=t==='bool'?el.checked:t==='num'?(el.value===''?'':Number(el.value)):t==='lines'?lines(el.value):el.value;
 if(t==='season-date')v=el.value.slice(-5);if(k.endsWith('.r'))v=Number(v);
 setPath(C,k,v);admSave(k.startsWith('site.'));
 if(t==='bool'&&e.type==='change'){const row=el.closest('.adm-row,.adm-item');if(row&&k.endsWith('.hidden'))row.classList.toggle('is-hidden',el.checked)}
}
function tourSeasonEditor(t,i){
 if(!t.seasons)t.seasons=tourSeasons(t);if(!t.routePins)t.routePins=tourPins(t);
  return card('Сезоны, города выезда и цены',`<p class="hint">Даты начала и окончания повторяются ежегодно. Последний день включён в сезон. Зимний период может переходить через Новый год. Между сезонами экскурсия недоступна. Цены и расписание выбираются по дате поездки и городу выезда. Пустая цена индивидуальной поездки — по запросу; указанная — за всю группу.</p>${t.seasons.map((s,j)=>{const k=x=>`tours.${i}.seasons.${j}.${x}`;return `<details class="season-editor" open><summary>${esc(s.name)}</summary><div class="adm-grid3">${F.text(k('name'),'Название сезона')}<label class="field"><span>Начало сезона · день и месяц</span><input class="input" type="date" data-k="${k('start')}" data-t="season-date" value="${new Date().getFullYear()}-${esc(String(s.start).slice(-5))}" required></label><label class="field"><span>Конец сезона · день и месяц</span><input class="input" type="date" data-k="${k('end')}" data-t="season-date" value="${new Date().getFullYear()+(tourSeasonEnd(t.seasons,s)<String(s.start).slice(-5)?1:0)}-${esc(tourSeasonEnd(t.seasons,s))}" required></label>${F.select(k('mode'),'Доступность',[['group','Групповая'],['individual','Только индивидуальная'],['both','Групповая и индивидуальная'],['closed','Закрыто · скрыть с сайта']])}</div>${(s.departures||[]).map((d,n)=>{const dk=x=>k(`departures.${n}.${x}`);return `<fieldset class="departure-editor"><legend>${esc(d.city||'Город выезда')}</legend><div class="adm-grid">${F.text(dk('city'),'Город выезда')}${F.bool(dk('enabled'),'Выезд из города доступен')}</div><div class="adm-grid3">${F.num(dk('adult'),'Групповая · взрослый, ₽','1')}${F.num(dk('child'),'Групповая · ребёнок, ₽','1')}${F.lines(dk('times'),'Время выезда',2,'Например 09:00, каждое время с новой строки')}</div><div class="adm-grid">${F.num(dk('individualPrice'),'Индивидуальная · за группу, ₽','1')}${F.num(dk('maxPeople'),'Индивидуальная · максимум гостей','1')}</div><div class="departure-days"><span>Дни выезда:</span>${['Вс','Пн','Вт','Ср','Чт','Пт','Сб'].map((name,day)=>F.bool(dk('days.'+day),name)).join('')}</div><button type="button" class="btn btn-ghost small danger" data-tour-action="remove-city" data-tour="${i}" data-season="${j}" data-city="${n}">Удалить город</button></fieldset>`}).join('')}<button type="button" class="btn btn-ghost small" data-tour-action="add-city" data-tour="${i}" data-season="${j}">+ Добавить город выезда</button></details>`}).join('')}`)+card('Остановки маршрута',routeStopsEditor(t,i));
}
document.addEventListener('click',e=>{const b=e.target.closest('[data-tour-action]');if(!b||!serverAdmin)return;const i=Number(b.dataset.tour),t=C.tours[i];if(!t)return;const s=t.seasons?.[Number(b.dataset.season)],n=Number(b.dataset.city);switch(b.dataset.tourAction){case 'add-city':s.departures.push({city:'Новый город '+(s.departures.length+1),enabled:false,adult:0,child:0,times:['09:00'],days:{0:true,1:true,2:true,3:true,4:true,5:true,6:true},individualPrice:null,maxPeople:6});break;case 'remove-city':s.departures.splice(n,1);break;case 'pin-add':{const pin=stopCatalog().find(p=>!t.routePins.includes(p.id))?.id;if(pin)t.routePins.push(pin);break}case 'pin-remove':t.routePins.splice(Number(b.dataset.pinIndex),1);if(Array.isArray(t.routeStays))t.routeStays.splice(Number(b.dataset.pinIndex),1);break;case 'pin-down':{const at=Number(b.dataset.pinIndex);if(at<t.routePins.length-1){[t.routePins[at],t.routePins[at+1]]=[t.routePins[at+1],t.routePins[at]];if(Array.isArray(t.routeStays))[t.routeStays[at],t.routeStays[at+1]]=[t.routeStays[at+1]??'',t.routeStays[at]??'']}break}case 'pin-up':{const at=Number(b.dataset.pinIndex);if(at>0){[t.routePins[at-1],t.routePins[at]]=[t.routePins[at],t.routePins[at-1]];if(Array.isArray(t.routeStays))[t.routeStays[at-1],t.routeStays[at]]=[t.routeStays[at]??'',t.routeStays[at-1]??'']}break}}saveContent();ADM_RENDER.tour(t.id)});
