let moderationLoading=false;
async function refreshModeration(){if(!serverAdmin||moderationLoading||parseHash().parts[1]!=='moderation')return;moderationLoading=true;try{await serverQueue;const data=await api('/api/moderation');serverLists.diary=data.diary;if(current==='admin'&&parseHash().parts[1]==='moderation'){const selected=$('#moderation-filter')?.value||'all';renderModeration();const filter=$('#moderation-filter');if(filter){filter.value=selected;$$('[data-mod-status]').forEach(n=>n.hidden=selected!=='all'&&n.dataset.modStatus!==selected)}$('#admMain').insertAdjacentHTML('afterbegin','<p class="hint" role="status">Очередь обновляется автоматически · <button class="linkbtn" type="button" data-refresh-moderation>Обновить</button></p>')}}catch(err){toast('Не удалось обновить очередь: '+err.message)}finally{moderationLoading=false}}
ADM_RENDER.moderation=function(){renderModeration();refreshModeration()};
document.addEventListener('click',e=>{if(e.target.closest('[data-refresh-moderation]'))refreshModeration()});
setInterval(()=>{if(!document.hidden)refreshModeration()},15000);
addEventListener('focus',refreshModeration);
function orderStatusSelect(order,kind){const status=order.status==='private'?'pending':order.status||'pending',options=kind==='bookings'?['pending','paid','completed','cancelled']:['pending','confirmed','completed','cancelled'];return `<select class="input" data-order-status="${esc(order.code)}" data-order-kind="${kind}" data-current-status="${status}" aria-label="Статус заказа ${esc(order.code)}">${options.map(v=>`<option value="${v}" ${v===status?'selected':''}>${orderStatusLabel(v)}</option>`).join('')}</select>`}
document.addEventListener('change',async e=>{const select=e.target;if(!select.dataset.orderStatus)return;if(select.value==='needs_info'){const root=select.closest('.order-admin-tools');const editor=root?.querySelector('.order-manager-editor'),question=root?.querySelector('.order-clarification-editor');if(editor)editor.open=true;if(question)question.open=true;root?.querySelector('[data-clarification-field]')?.focus();toast('Выберите пункт уточнения и отправьте запрос');return}select.disabled=true;try{await serverQueue;const result=await api('/api/order-status',{method:'PUT',body:JSON.stringify({id:select.dataset.orderStatus,kind:select.dataset.orderKind,status:select.value})});const item=serverLists[select.dataset.orderKind]?.find(x=>x.code===select.dataset.orderStatus);if(item)Object.assign(item,result.order||{status:select.value});const answerBox=select.closest('.order-admin-tools')?.querySelector('.clarification-admin-answer');if(answerBox&&item)answerBox.outerHTML=clarificationAdminAnswerHTML(item);select.dataset.currentStatus=select.value;toast('Статус сохранён');applyRequestQueue()}catch(err){select.value=select.dataset.currentStatus;toast(err.message)}finally{select.disabled=false}});
