ADM_RENDER.services=function(){const list=serviceItems();$('#admMain').innerHTML=`<header class="adm-head"><h1>Полезное</h1><p class="sub">Рекомендуемые услуги. Без отдельной ссылки кнопка использует телефон «Апсуа Тур» из раздела контактов.</p><button class="btn btn-sea" type="button" data-service-action="add">Добавить услугу</button></header>${list.map((x,i)=>card(esc(x.title||'Новая услуга'),`<div class="adm-grid">${F.text(`services.${i}.title`,'Название')}${F.text(`services.${i}.category`,'Категория')}${F.text(`services.${i}.partner`,'Партнёр / организация')}${F.text(`services.${i}.location`,'Место')}${F.text(`services.${i}.price`,'Цена или условия','Например: по запросу')}${F.text(`services.${i}.button`,'Текст кнопки')}</div>${F.area(`services.${i}.short`,'Короткое описание',2)}${F.area(`services.${i}.description`,'Подробная информация',5)}${F.photo(`services.${i}.photo`,'Фото услуги',['sea',0])}${F.text(`services.${i}.url`,'Ссылка или контакт','https://… / tel:+7… / mailto:…')}<p class="hint">Можно указать сайт партнёра, Telegram, WhatsApp, телефон или почту. Для мессенджеров используйте полную https-ссылку.</p><div class="adm-item-foot">${F.bool(`services.${i}.hidden`,'Скрыть с сайта')}<button class="btn btn-ghost small" type="button" data-service-action="up" data-index="${i}" ${i===0?'disabled':''}>Выше</button><button class="btn btn-ghost small" type="button" data-service-action="down" data-index="${i}" ${i===list.length-1?'disabled':''}>Ниже</button><a class="btn btn-ghost small" href="#/useful/${encodeURIComponent(x.id)}">Открыть</a><button class="btn btn-ghost small danger" type="button" data-service-action="delete" data-index="${i}">Удалить</button></div>`)).join('')}`};
document.addEventListener('click',e=>{const button=e.target.closest('[data-service-action]');if(!button||!serverAdmin)return;const list=serviceItems(),i=Number(button.dataset.index),action=button.dataset.serviceAction;if(action==='add')list.unshift({id:newId('service-'),title:'Новая услуга',category:'Полезное',short:'',description:'',photo:'',partner:'',location:'',price:'',url:'',button:'Связаться',hidden:true});else if(action==='delete'){if(!confirm('Удалить эту услугу?'))return;list.splice(i,1)}else if(action==='up')mv(list,i,i-1);else if(action==='down')mv(list,i,i+1);saveContent();ADM_RENDER.services()});
