ADM_RENDER.whatsnew=function(){$('#admMain').innerHTML=`<header class="adm-head"><h1>Что нового?</h1><p class="sub">Доработки и функции сайта с версии 1.0. Даты — по московскому времени.</p></header><section class="panel news-controls"><label class="field">Поиск<input class="input" type="search" data-news-filter="search" value="${esc(newsState.search)}" placeholder="Название, изменение или версия"></label><div class="news-filter-grid"><label class="field">С даты<input class="input" type="date" data-news-filter="from" value="${newsState.from}"></label><label class="field">По дату<input class="input" type="date" data-news-filter="to" value="${newsState.to}"></label><label class="field">Тип<select class="input" data-news-filter="type"><option value="">Все изменения</option>${Object.entries(newsKinds).map(([k,v])=>`<option value="${k}" ${newsState.type===k?'selected':''}>${v}</option>`).join('')}</select></label><label class="field">Значимость<select class="input" data-news-filter="priority"><option value="">Все отметки</option>${Object.entries(newsPriorities).map(([k,[icon,v]])=>`<option value="${k}" ${newsState.priority===k?'selected':''}>${icon} ${v}</option>`).join('')}</select></label><label class="field">Порядок<select class="input" data-news-filter="sort"><option value="newest" ${newsState.sort==='newest'?'selected':''}>Сначала новые</option><option value="oldest" ${newsState.sort==='oldest'?'selected':''}>Сначала старые</option><option value="version" ${newsState.sort==='version'?'selected':''}>От версии 1.0</option></select></label><button class="btn btn-ghost small" type="button" data-news-reset>Сбросить</button></div></section><section id="newsResults" aria-label="История обновлений"></section>`;if(changelogState==='failed')changelogState='idle';renderNewsResults()};
document.addEventListener('click',e=>{const page=e.target.closest('[data-news-page]');if(page){newsState.page+=Number(page.dataset.newsPage);renderNewsResults();$('#newsResults')?.scrollIntoView({block:'start'});}if(e.target.closest('[data-news-reset]')){Object.assign(newsState,{search:'',from:'',to:'',type:'',priority:'',sort:'newest',page:0});ADM_RENDER.whatsnew()}});
