const adminTourQuery={name:'',type:'',district:'',sort:'manual'};
function adminTourText(text){return String(text||'').normalize('NFKC').toLocaleLowerCase('ru-RU').replaceAll('ё','е').trim()}
function adminTourMatches(){const term=adminTourText(adminTourQuery.name),list=C.tours.map((tour,index)=>({tour,index})).filter(({tour})=>(!term||adminTourText(tour.title).includes(term))&&(!adminTourQuery.type||tour.cat===adminTourQuery.type)&&(!adminTourQuery.district||tour.district===adminTourQuery.district));const label=(t,k)=>k==='type'?(CAT[t.cat]||t.cat||''):k==='district'?(DMAP[t.district]?.name||t.district||''):(t.title||'');if(adminTourQuery.sort!=='manual')list.sort((a,b)=>label(a.tour,adminTourQuery.sort).localeCompare(label(b.tour,adminTourQuery.sort),'ru')||String(a.tour.title).localeCompare(String(b.tour.title),'ru')||a.index-b.index);return list}
function adminTourSearchHTML(){return `<section class="admin-tour-filters"><label class="field admin-tour-name"><span>Название экскурсии</span><input type="search" class="input" data-admin-tour-filter="name" list="adminTourNames" value="${esc(adminTourQuery.name)}" placeholder="Начните вводить название…" autocomplete="off"><datalist id="adminTourNames">${C.tours.map(t=>`<option value="${esc(t.title)}"></option>`).join('')}</datalist></label><label class="field"><span>Тип</span><select class="input" data-admin-tour-filter="type"><option value="">Все типы</option>${Object.entries(CAT).map(([k,v])=>`<option value="${k}" ${adminTourQuery.type===k?'selected':''}>${esc(v)}</option>`).join('')}</select></label><label class="field"><span>Район</span><select class="input" data-admin-tour-filter="district"><option value="">Все районы</option>${DISTRICTS.map(d=>`<option value="${d.id}" ${adminTourQuery.district===d.id?'selected':''}>${esc(d.name)}</option>`).join('')}</select></label><label class="field"><span>Порядок</span><select class="input" data-admin-tour-filter="sort">${[['manual','Как в каталоге'],['name','По названию'],['type','По типу'],['district','По району']].map(([k,v])=>`<option value="${k}" ${adminTourQuery.sort===k?'selected':''}>${v}</option>`).join('')}</select></label><button type="button" class="btn btn-ghost small" data-admin-tour-reset>Сбросить</button><span id="adminTourCount" role="status" aria-live="polite"></span></section>`}
function applyAdminTourSearch(){const root=$('#adminTourList');if(!root)return;const matches=adminTourMatches(),ranks=new Map(matches.map((x,i)=>[x.index,i])),rows=$$('[data-admin-tour-index]',root);rows.forEach(row=>row.hidden=!ranks.has(Number(row.dataset.adminTourIndex)));if(adminTourQuery.sort==='manual')rows.sort((a,b)=>Number(a.dataset.adminTourIndex)-Number(b.dataset.adminTourIndex));else rows.sort((a,b)=>(ranks.get(Number(a.dataset.adminTourIndex))??99999)-(ranks.get(Number(b.dataset.adminTourIndex))??99999));rows.forEach(row=>root.appendChild(row));const count=$('#adminTourCount');if(count)count.textContent='Найдено: '+matches.length+' из '+C.tours.length;const empty=$('#adminTourEmpty');if(empty)empty.hidden=matches.length>0}
const adminToursBeforeSearch=ADM_RENDER.tours;
ADM_RENDER.tours=function(parts){adminToursBeforeSearch(parts);if(parts[2])return;const header=$('#admMain .adm-head');header?.insertAdjacentHTML('afterend',adminTourSearchHTML());$('#adminTourList')?.insertAdjacentHTML('afterend','<div class="empty" id="adminTourEmpty" hidden>Экскурсии не найдены. Измените название, тип или район.</div>');applyAdminTourSearch()};
document.addEventListener('input',e=>{const key=e.target.dataset.adminTourFilter;if(!key||!(key in adminTourQuery))return;adminTourQuery[key]=e.target.value;applyAdminTourSearch()});
document.addEventListener('click',e=>{if(!e.target.closest('[data-admin-tour-reset]'))return;Object.assign(adminTourQuery,{name:'',type:'',district:'',sort:'manual'});$$('[data-admin-tour-filter]').forEach(field=>field.value=adminTourQuery[field.dataset.adminTourFilter]);applyAdminTourSearch()});
function pendingTourKey(){return 'apsua-new-tour-banner:'+String(serverIdentity?.id||'admin')}
function pendingTourIds(){try{const ids=JSON.parse(localStorage.getItem(pendingTourKey())||'[]');return Array.isArray(ids)?ids:[]}catch{return []}}
function markNewTour(id){try{localStorage.setItem(pendingTourKey(),JSON.stringify([...new Set([...pendingTourIds(),id])]))}catch{}}
function forgetNewTour(id){try{localStorage.setItem(pendingTourKey(),JSON.stringify(pendingTourIds().filter(x=>x!==id)))}catch{}}
function askTourBanner(t){return new Promise(resolve=>{const dialog=document.createElement('dialog');dialog.className='tour-banner-dialog';dialog.innerHTML=`<h2>Показывать экскурсию в баннере?</h2><p>${esc(t.title)}</p><p class="sub">Она появится среди популярных маршрутов на главной.${t.hidden?' Сейчас экскурсия скрыта: показ начнётся после включения её видимости.':''}</p><div class="tour-banner-actions"><button type="button" class="btn btn-sea" data-banner-choice="yes">Показывать</button><button type="button" class="btn btn-ghost" data-banner-choice="no">Не показывать</button><button type="button" class="btn btn-ghost small" data-banner-choice="cancel">Отмена</button></div>`;const finish=value=>{dialog.close();dialog.remove();resolve(value)};dialog.addEventListener('click',e=>{const button=e.target.closest('[data-banner-choice]');if(button)finish(button.dataset.bannerChoice==='cancel'?null:button.dataset.bannerChoice==='yes')});dialog.addEventListener('cancel',e=>{e.preventDefault();finish(null)});document.body.append(dialog);dialog.showModal()})}
async function saveTourExplicitly(id){const tour=tourById(id);if(!tour||!serverAdmin)return;const button=$('[data-admin-save-tour]');if(button?.disabled)return;const error=validateTourSettings(C.tours)||validateSiteConfig(C);if(error){admStatus(error,true);toast(error);return}if(button)button.disabled=true;try{if(pendingTourIds().includes(id)){const choice=await askTourBanner(tour);if(choice===null)return;tour.popular=choice;const index=C.tours.findIndex(x=>x.id===id),toggle=$(`[data-k="tours.${index}.popular"]`);if(toggle)toggle.checked=choice}clearTimeout(saveT);const work=async()=>{const content=normalizeMedia(clone(C));delete content.site.adminPass;admStatus('Сохранение на сервере…');const payload=serverEditor?{patch:Object.fromEntries(['tours','services','popularLimit','servicesPartnerVersion','routeStops'].filter(k=>Object.hasOwn(content,k)).map(k=>[k,content[k]])),revision:contentRevision}:{content,revision:contentRevision};const data=await api('/api/content',{method:'PUT',body:JSON.stringify(payload)});contentRevision=data.revision;forgetNewTour(id);admStatus('Сохранено на сервере ✓');toast('Экскурсия сохранена')};const result=serverQueue.then(work);serverQueue=result.catch(()=>{});await result}catch(err){admStatus('Не сохранено: '+err.message,true);toast(err.message)}finally{if(button?.isConnected)button.disabled=false}}
document.addEventListener('click',e=>{const button=e.target.closest('[data-admin-save-tour]');if(button){e.preventDefault();saveTourExplicitly(button.dataset.adminSaveTour)}});
admSave=function(chrome){clearTimeout(saveT);stageAdminContent();if(chrome)renderChrome()};
function setupAdminSave(){const root=$('#admMain');if(!root)return;if(!adminDirty&&!adminSaving)resetAdminBaseline();if(!$('#adminSaveBar'))root.insertAdjacentHTML('afterbegin','<div class="admin-save-bar" id="adminSaveBar"><span id="adminDraftStatus" role="status" aria-live="polite"></span><button class="btn btn-sea small" type="button" data-admin-save>Сохранить</button></div>');adminLastHash=location.hash;updateAdminSaveState()}
for(const key of Object.keys(ADM_RENDER)){const original=ADM_RENDER[key];ADM_RENDER[key]=function(...args){const result=original.apply(this,args);setupAdminSave();return result}}
async function saveAdminChanges(){if(adminSaving)return false;const invalid=$('#admMain [data-k]:invalid,#admMain [data-stop-pick]:invalid');if(invalid){invalid.reportValidity?.();toast('Проверьте значение поля');return false}const error=validateTourSettings(C.tours)||validateSiteConfig(C);if(error){admStatus(error,true);toast(error);return false}adminSaving=true;updateAdminSaveState();try{for(const id of pendingTourIds().filter(id=>C.tours.some(t=>t.id===id))){const t=tourById(id),choice=await askTourBanner(t);if(choice===null)return false;t.popular=choice;const index=C.tours.findIndex(x=>x.id===id),toggle=$(`[data-k="tours.${index}.popular"]`);if(toggle)toggle.checked=choice}clearTimeout(saveT);const snapshot=clone(C),content=normalizeMedia(clone(snapshot));delete content.site.adminPass;const work=async()=>{const payload=serverEditor?{patch:Object.fromEntries(['tours','services','popularLimit','servicesPartnerVersion','routeStops'].filter(k=>Object.hasOwn(content,k)).map(k=>[k,content[k]])),revision:contentRevision}:{content,revision:contentRevision};const data=await api('/api/content',{method:'PUT',body:JSON.stringify(payload)});contentRevision=data.revision};const result=serverQueue.then(work);serverQueue=result.catch(()=>{});await result;adminBaseline=snapshot;adminDirty=JSON.stringify(C)!==JSON.stringify(snapshot);snapshot.tours.forEach(t=>forgetNewTour(t.id));admStatus('Сохранено на сервере ✓');toast('Изменения сохранены');window.dispatchEvent(new Event('admin-content-saved'));return true}catch(err){admStatus('Не сохранено: '+err.message,true);toast('Не сохранено: '+err.message);return false}finally{adminSaving=false;updateAdminSaveState()}}
saveTourExplicitly=function(){return saveAdminChanges()};
function discardAdminChanges(){if(!adminBaseline)return;const ids=new Set(adminBaseline.tours.map(t=>t.id));C.tours.filter(t=>!ids.has(t.id)).forEach(t=>forgetNewTour(t.id));C=clone(adminBaseline);clearTimeout(saveT);adminDirty=false;updateAdminSaveState();renderChrome();window.dispatchEvent(new Event('admin-content-discarded'))}
function askUnsavedAdmin(){return new Promise(resolve=>{const dialog=document.createElement('dialog');dialog.className='tour-banner-dialog';dialog.innerHTML='<h2>Сохранить изменения?</h2><p class="sub">В админке есть несохранённые изменения.</p><div class="tour-banner-actions"><button type="button" class="btn btn-sea" data-exit-choice="yes">Да, сохранить</button><button type="button" class="btn btn-ghost" data-exit-choice="no">Нет, выйти</button></div>';const finish=value=>{dialog.close();dialog.remove();resolve(value)};dialog.addEventListener('click',e=>{const button=e.target.closest('[data-exit-choice]');if(button)finish(button.dataset.exitChoice)});dialog.addEventListener('cancel',e=>{e.preventDefault();finish(null)});document.body.append(dialog);dialog.showModal()})}
async function exitAdminDraft(proceed){if(adminExitBusy||adminSaving)return;adminExitBusy=true;try{const choice=await askUnsavedAdmin();if(choice==='yes'){if(!await saveAdminChanges())return}else if(choice==='no')discardAdminChanges();else return;adminNavigationPermit=true;proceed();adminNavigationPermit=false}catch(err){toast(err.message)}finally{adminExitBusy=false}}
function guardAdminClick(e){if(adminNavigationPermit||!adminDirty)return;const logout=e.target.closest('[data-logout]'),link=e.target.closest('a[href]');if(!logout&&!link)return;if(link&&(link.target==='_blank'||link.hasAttribute('download')))return;const url=link?new URL(link.href,location.href):null;if(url&&url.href===location.href)return;e.preventDefault();e.stopImmediatePropagation();exitAdminDraft(()=>{if(logout){adminNavigationPermit=true;logout.click()}else if(url.origin===location.origin&&url.pathname===location.pathname&&url.search===location.search){adminLastHash=url.hash;location.hash=url.hash}else location.href=url.href})}
window.addEventListener('beforeunload',e=>{if(adminDirty||adminSaving){e.preventDefault();e.returnValue=''}});
document.addEventListener('click',e=>{if(e.target.closest('[data-admin-save]')){e.preventDefault();saveAdminChanges()}});
function setBannerPhotos(target,photos){if(!['hero','transfer'].includes(target))return;C[target].photos=photos.slice();C[target].photo=photos[0]||'';stageAdminContent()}
async function uploadBannerPhotos(target,files){if(!serverAdmin||serverEditor||!['hero','transfer'].includes(target))return;const added=[];for(const file of files){if(!file.type.startsWith('image/'))continue;const photo=await storePhoto(file,1800);if(photo)added.push(photo)}if(added.length){setBannerPhotos(target,[...bannerPhotos(target),...added]);admRerender();toast('Фото добавлены. Нажмите «Сохранить».')}}
document.addEventListener('change',e=>{const target=e.target.dataset.bannerPhotos;if(target&&e.target.files?.length)uploadBannerPhotos(target,[...e.target.files])});
document.addEventListener('click',e=>{const button=e.target.closest('[data-banner-action]');if(!button||!serverAdmin||serverEditor)return;const target=button.dataset.bannerTarget,photos=bannerPhotos(target),index=Number(button.dataset.bannerIndex);if(button.dataset.bannerAction==='delete')photos.splice(index,1);else{const next=index+(button.dataset.bannerAction==='left'?-1:1);if(next<0||next>=photos.length)return;[photos[index],photos[next]]=[photos[next],photos[index]]}setBannerPhotos(target,photos);admRerender()});
document.addEventListener('drop',e=>{const box=e.target.closest('[data-banner-drop]');if(!box)return;e.preventDefault();box.classList.remove('drag');uploadBannerPhotos(box.dataset.bannerDrop,[...(e.dataTransfer.files||[])])});
// Keep essential travel details editable rather than guessing route conditions.
const adminTourBeforePretrip=ADM_RENDER.tour;
ADM_RENDER.tour=function(id){adminTourBeforePretrip(id);const i=C.tours.findIndex(t=>t.id===id);if(i<0)return;const danger=$('#admMain .adm-danger');const fields=card('Памятка перед бронированием',`<div class="adm-grid">${F.text(`tours.${i}.preTrip.children`,'Подходит ли детям','Например: детям от 6 лет')}${F.text(`tours.${i}.preTrip.walking`,'Пешая нагрузка','Например: лёгкая, прогулка 30 минут')}</div>${F.area(`tours.${i}.preTrip.packing`,'Что взять с собой',2,'Обувь, одежда, документы — по условиям маршрута')}`);if(danger)danger.insertAdjacentHTML('beforebegin',fields);else $('#admMain').insertAdjacentHTML('beforeend',fields);setupCompactAdmin();setupAdminSave()};
orderStatusSelect=function(order,kind){const status=order.status==='private'?'pending':order.status||'pending',options=kind==='bookings'?['pending','needs_info','confirmed','awaiting_payment','paid','completed','rejected','cancelled']:['pending','needs_info','confirmed','awaiting_payment','paid','completed','rejected','cancelled'];return `<div class="order-admin-tools"><select class="input" data-order-status="${esc(order.code)}" data-order-kind="${kind}" data-current-status="${status}" aria-label="Статус заказа ${esc(order.code)}">${options.map(value=>`<option value="${value}" ${value===status?'selected':''}>${orderStatusLabel(value)}</option>`).join('')}</select><details class="order-manager-editor"><summary>Ответственный и детали</summary><label class="field">Ответственный сотрудник<input class="input" data-order-assignee maxlength="100" value="${esc(order.assignee||'')}"></label><label class="field">Место встречи<input class="input" data-order-meeting maxlength="300" value="${esc(order.meetingPoint||'')}"></label><label class="field">Телефон организатора<input class="input" data-order-contact type="tel" maxlength="80" value="${esc(order.contactPhone||'')}"></label><label class="field">Пояснение<textarea class="input" data-order-note maxlength="1000" rows="2">${esc(order.managerNote||'')}</textarea></label><button type="button" class="btn btn-sea small" data-save-order-details="${esc(order.code)}" data-order-kind="${kind}">Сохранить детали</button></details></div>`};
document.addEventListener('click',async e=>{if(e.target.closest('[data-refresh-orders]'))refreshMyOrders();if(e.target.closest('[data-open-review]')){const form=$('#revForm');const compose=form?.closest('details'),section=compose?.parentNode?.closest('details');if(section)section.open=true;if(compose)compose.open=true;form?.scrollIntoView({block:'start',behavior:'smooth'})}const button=e.target.closest('[data-save-order-details]');if(!button||button.disabled||!serverAdmin||serverEditor)return;const root=button.closest('.order-admin-tools'),select=$('[data-order-status]',root);button.disabled=true;try{await serverQueue;const data=await api('/api/order-status',{method:'PUT',body:JSON.stringify({id:button.dataset.saveOrderDetails,kind:button.dataset.orderKind,status:select.value,meetingPoint:$('[data-order-meeting]',root).value,contactPhone:$('[data-order-contact]',root).value,managerNote:$('[data-order-note]',root).value,assignee:$('[data-order-assignee]',root).value,...paymentFromOrderEditor(root)})});const order=serverLists[button.dataset.orderKind]?.find(x=>x.code===button.dataset.saveOrderDetails);if(order)Object.assign(order,data.order);root.dataset.paymentDirty='';toast('Детали сохранены');adminApp?.applyRequestQueue()}catch(err){toast(err.message)}finally{if(button.isConnected)button.disabled=false}});
ADM_TABS.push(['visual','Визуальный редактор']);
adminGroups.find(g=>g[0]==='Оформление')[1].push('visual');
ADM_RENDER.visual=function(){$('#admMain').innerHTML='<header class="adm-head"><h1>Визуальный редактор</h1><p class="sub">Выбирайте элементы прямо на сайте. Отдельное оформление для телефона и ПК, мгновенный предпросмотр, отмена и повтор действий.</p></header>'+card('Редактирование страницы','<p class="sub">Выберите элемент на странице. Для перехода переключитесь в «Просмотр». Настройки публикуются после «Сохранить».</p><button class="btn btn-sea small" type="button" data-visual-open>Открыть редактор сайта</button>')+card('История оформления · последние 10 сохранений','<p class="hint">Откат возвращает оформление до выбранного сохранения. Остальные данные сайта сохраняются.</p><div data-visual-history>Загрузка…</div>');setupCompactAdmin();setupAdminSave();window.apsuaVisualHistory?.mount($('#admMain [data-visual-history]'))};
function routeStopsEditor(t,i){const choices=stopCatalog();return `<p class="hint">Километры и время в пути между остановками сайт считает сам по дорогам. Выберите остановки по порядку. Начните вводить название, чтобы найти в списке. Новые остановки добавляются в отдельном справочнике.</p><a class="btn btn-ghost small" href="#/admin/stops">Открыть справочник остановок</a><datalist id="tourStopChoices">${choices.map(s=>`<option value="${esc(s.name)}"></option>`).join('')}</datalist><ol class="route-editor">${t.routePins.map((id,j)=>`<li><label class="field"><span>Остановка ${j+1}</span><input class="input" list="tourStopChoices" data-stop-pick data-tour="${i}" data-stop-index="${j}" value="${esc(PIN_NAMES[id]||'')}" placeholder="Введите название…" autocomplete="off"></label><label class="field route-stay"><span>Сколько стоим</span><input class="input" data-k="tours.${i}.routeStays.${j}" value="${esc((t.routeStays||[])[j]||'')}" maxlength="60" placeholder="Например: 20 мин"></label><div class="route-stop-actions"><button type="button" class="ibtn" data-tour-action="pin-up" data-tour="${i}" data-pin-index="${j}" aria-label="Выше" ${j?'':'disabled'}>↑</button><button type="button" class="ibtn" data-tour-action="pin-down" data-tour="${i}" data-pin-index="${j}" aria-label="Ниже" ${j===t.routePins.length-1?'disabled':''}>↓</button><button type="button" class="btn btn-ghost small danger" data-tour-action="pin-remove" data-tour="${i}" data-pin-index="${j}">Удалить</button></div></li>`).join('')}</ol><button type="button" class="btn btn-ghost small" data-tour-action="pin-add" data-tour="${i}">+ Добавить остановку</button>`}
ADM_TABS.push(['stops','Остановки маршрутов']);
ADM_RENDER.stops=function(){C.routeStops??=clone(BASE_STOPS);const used=id=>C.tours.some(t=>t.pin===id||(t.routePins||[]).includes(id));$('#admMain').innerHTML=`<header class="adm-head"><h1>Остановки маршрутов</h1><p class="sub">Общий список для экскурсий. Координаты необязательны для списка, но нужны для маршрута на карте.</p></header>${card('Справочник остановок',`<input class="input" type="search" data-stop-search placeholder="Найти остановку…" aria-label="Поиск остановок"><div class="stop-catalog">${C.routeStops.map((s,i)=>`<details class="stop-catalog-row" data-stop-row ${s.name?'':'open'}><summary>${esc(s.name||'Новая остановка')}</summary><div class="adm-grid">${F.text(`routeStops.${i}.name`,'Название')}${F.select(`routeStops.${i}.district`,'Район',DISTRICTS.map(d=>[d.id,d.name]))}${F.text(`routeStops.${i}.paid`,'Платный вход · необязательно','Например: вход ~500 ₽')}</div>${F.photo(`routeStops.${i}.photo`,'Фото остановки',['mount',0])}<details class="stop-coordinates"><summary>Координаты для карты · необязательно</summary><div class="adm-grid">${F.num(`routeStops.${i}.lat`,'Широта','any')}${F.num(`routeStops.${i}.lon`,'Долгота','any')}</div></details><button class="btn btn-ghost small danger" type="button" data-stop-delete="${i}" ${used(s.id)?'disabled':''}>Удалить</button>${used(s.id)?'<small class="hint">Используется в экскурсиях: сначала уберите из маршрутов.</small>':''}</details>`).join('')}</div><button class="btn btn-ghost small" type="button" data-stop-add>+ Добавить остановку</button>`)}`;setupCompactAdmin();setupAdminSave()};
document.addEventListener('input',e=>{const el=e.target;if(el.matches('[data-stop-pick]')){const stop=stopCatalog().find(x=>x.name.toLocaleLowerCase('ru')===el.value.trim().toLocaleLowerCase('ru'));el.setCustomValidity(stop?'':'Выберите остановку из списка или добавьте её в справочник');if(stop){C.tours[Number(el.dataset.tour)].routePins[Number(el.dataset.stopIndex)]=stop.id;stageAdminContent()}else{adminDirty=true;updateAdminSaveState()}}if(el.matches('[data-stop-search]'))$$('[data-stop-row]').forEach(row=>{const input=$('input[data-k$=".name"]',row);row.hidden=!(input?.value||row.textContent).toLocaleLowerCase('ru').includes(el.value.toLocaleLowerCase('ru'))})});
document.addEventListener('click',e=>{if(!serverAdmin)return;if(e.target.closest('[data-stop-add]')){C.routeStops??=clone(BASE_STOPS);C.routeStops.push({id:newId('stop-'),name:'',district:'gudauta',lat:'',lon:''});stageAdminContent();ADM_RENDER.stops()}const button=e.target.closest('[data-stop-delete]');if(button){const stop=C.routeStops[Number(button.dataset.stopDelete)];if(C.tours.some(t=>t.pin===stop.id||(t.routePins||[]).includes(stop.id)))return toast('Остановка используется в экскурсии');C.routeStops.splice(Number(button.dataset.stopDelete),1);syncRouteStops();stageAdminContent();ADM_RENDER.stops()}});
const transferAdminBeforeExtras=ADM_RENDER.transfer;
ADM_RENDER.transfer=function(){ensureTransferConfig();transferAdminBeforeExtras();$('#admMain').insertAdjacentHTML('beforeend',card('Сезон группового трансфера',`<p class="hint">Вне выбранного периода доступны только индивидуальные трансферы. Даты повторяются ежегодно, последний день включён. Начальный период: 1 мая–31 октября.</p>${F.bool('transfer.groupPolicy.enabled','Групповой трансфер разрешён в сезон')}<div class="adm-grid"><label class="field"><span>Начало сезона · день и месяц</span><input class="input" type="date" data-k="transfer.groupPolicy.start" data-t="season-date" value="${new Date().getFullYear()}-${esc(C.transfer.groupPolicy.start)}" required></label><label class="field"><span>Конец сезона · день и месяц</span><input class="input" type="date" data-k="transfer.groupPolicy.end" data-t="season-date" value="${new Date().getFullYear()+(C.transfer.groupPolicy.end<C.transfer.groupPolicy.start?1:0)}-${esc(C.transfer.groupPolicy.end)}" required></label></div>`)+card('Отели и точные адреса',`<p class="hint">Список отелей для каждого населённого пункта. На сайте выбор отеля подставит адрес, который турист сможет уточнить.</p><div class="hotel-catalog">${C.transfer.hotels.map((h,i)=>`<details class="hotel-catalog-row" ${h.name?'':'open'}><summary>${esc(h.name||'Новый отель')} · ${esc(C.transfer.to.find(c=>c.id===h.city)?.name||'')}</summary><div class="adm-grid">${F.select(`transfer.hotels.${i}.city`,'Город',C.transfer.to.map(x=>[x.id,x.name]))}${F.text(`transfer.hotels.${i}.name`,'Название отеля')}</div>${F.text(`transfer.hotels.${i}.address`,'Точный адрес')}<button class="btn btn-ghost small danger" type="button" data-hotel-delete="${i}">Удалить отель</button></details>`).join('')}</div><button class="btn btn-ghost small" type="button" data-hotel-add>+ Добавить отель</button>`));setupCompactAdmin();setupAdminSave()};
document.addEventListener('click',e=>{if(!serverAdmin||serverEditor)return;if(e.target.closest('[data-hotel-add]')){C.transfer.hotels.push({id:newId('hotel-'),city:C.transfer.to[0]?.id||'',name:'',address:''});stageAdminContent();ADM_RENDER.transfer()}const button=e.target.closest('[data-hotel-delete]');if(button){C.transfer.hotels.splice(Number(button.dataset.hotelDelete),1);stageAdminContent();ADM_RENDER.transfer()}});
function adminOrderAmount(order){const value=Object.hasOwn(order,'total')?order.total:order.price;return value==null||!Number.isFinite(Number(value))?null:Number(value)}
function compareAdminOrders(a,b,sort='attention'){const status=o=>o.status==='private'?'pending':o.status||'pending',rank=o=>status(o)==='pending'&&o.clarification?.answeredAt&&!o.clarification?.reviewedAt?0:({pending:1,needs_info:2,awaiting_payment:3,confirmed:4,paid:5,completed:6,rejected:7,cancelled:8}[status(o)]??9),created=o=>Number(o.createdAt||o.created||o.updatedAt)||Date.parse(o.at||o.d||'')||0,date=o=>o.date?o.date+'T'+(o.time||'00:00'):'9999',tie=()=>String(a.code||'').localeCompare(String(b.code||''));if(sort==='attention')return rank(a)-rank(b)||created(b)-created(a)||tie();if(sort==='newest')return created(b)-created(a)||tie();if(sort==='dateAsc'||sort==='dateDesc')return (sort==='dateDesc'?-1:1)*date(a).localeCompare(date(b))||tie();if(sort==='name')return String(a.name||'').localeCompare(String(b.name||''),'ru')||tie();if(sort==='priceAsc'||sort==='priceDesc'){const av=adminOrderAmount(a),bv=adminOrderAmount(b);if(av==null||bv==null)return av==null?(bv==null?tie():1):-1;return (sort==='priceDesc'?-1:1)*(av-bv)||tie()}return tie()}
function adminOrderTable(orders,kind){return `<div class="table-wrap admin-orders-scroll"><table class="rates admin-orders-table" data-admin-order-table="${kind}"><thead><tr><th>Заказ / маршрут</th><th>Дата и время</th><th>Клиент</th><th>Сумма</th><th>Статус / действия</th></tr></thead><tbody>${orders.map(order=>adminOrderRow({...order,kind},kind)).join('')}<tr data-order-empty hidden><td colspan="5">Нет заказов по выбранным фильтрам</td></tr></tbody></table></div>`}
function adminOrderRow(order,kind){const title=kind==='bookings'?tourById(order.tour)?.title||order.tour||'Экскурсия':order.route||'Трансфер',context=kind==='bookings'?[order.city,order.format==='individual'?'Индивидуальная':null,order.adults!=null?`${order.adults} взр.${order.kids?' + '+order.kids+' дет.':''}`:null]:[order.direction==='departure'?'Отъезд':order.direction==='arrival'?'Встреча':null,transferFormatLabel(order)],amount=adminOrderAmount(order),fields=[['Номер',order.code],['Город',order.city],['Формат',kind==='transfers'?transferFormatLabel(order):order.format==='individual'?'Индивидуальная':order.format==='group'?'Групповая':order.format],['Сезон',order.season],['Пассажиры',Array.isArray(order.passengerNames)?order.passengerNames.join(', '):''],['Адрес',order.address],['Отель',order.hotel],['Рейс / поезд',order.flight],['Связь',order.via],['Комментарий',order.note]],status=order.status==='private'?'pending':order.status||'pending';return `<tr data-request-code="${esc(order.code)}" data-request-kind="${kind}" data-request-status="${esc(status)}"><td data-label="Заказ"><b class="admin-order-title">${esc(title)}</b><small class="admin-order-context">${context.filter(Boolean).map(esc).join(' · ')}</small><details class="admin-order-full"><summary>Детали заказа</summary><dl>${fields.filter(([,value])=>value!==undefined&&value!==null&&value!=='').map(([label,value])=>`<div><dt>${esc(label)}</dt><dd>${esc(value)}</dd></div>`).join('')}</dl></details></td><td data-label="Дата"><b>${order.date?esc(shortDate(order.date)):'Не указана'}</b><small>${esc(order.time||'')}</small></td><td data-label="Клиент"><span ${profileTarget(order.uid)}>${esc(order.name||'Не указано')}</span><small>${esc(order.phone||'')}</small></td><td data-label="Сумма"><b>${amount==null?'По запросу':rub(amount)}</b></td><td data-label="Статус" class="admin-order-actions" data-status="${esc(status)}">${orderStatusSelect(order,kind)}</td></tr>`}
document.addEventListener('change',e=>{const key={requestQueueSort:'sort',requestQueueCity:'city',requestQueueFrom:'from',requestQueueTo:'to'}[e.target.id];if(key){requestQueueState[key]=e.target.value;applyRequestQueue()}});
document.addEventListener('click',e=>{if(!e.target.closest('[data-reset-order-filters]'))return;Object.assign(requestQueueState,{status:'all',kind:'all',query:'',city:'all',from:'',to:'',sort:'attention'});for(const [id,key]of [['requestQueueStatus','status'],['requestQueueKind','kind'],['requestQueueSearch','query'],['requestQueueCity','city'],['requestQueueFrom','from'],['requestQueueTo','to'],['requestQueueSort','sort']]){const input=$('#'+id);if(input)input.value=requestQueueState[key]}applyRequestQueue()});
function requestMatches(order,kind,state=requestQueueState){const status=order.status==='private'?'pending':order.status||'pending';return(state.status==='all'||state.status==='active'&&!['completed','rejected','cancelled'].includes(status)||state.status==='answered'&&status==='pending'&&order.clarification?.answeredAt&&!order.clarification?.reviewedAt||status===state.status)&&(state.kind==='all'||kind===state.kind)&&(!state.city||state.city==='all'||order.city===state.city||order.hotelCity===state.city||String(order.route||'').includes(state.city))&&(!state.from||order.date>=state.from)&&(!state.to||order.date<=state.to)&&(!state.query||[order.code,order.name,order.phone,order.assignee,order.route,order.address,order.hotel,order.city,tourById(order.tour)?.title].join(' ').toLocaleLowerCase('ru').includes(state.query.toLocaleLowerCase('ru')))}
function applyRequestQueue(){let shown=0;const rows=$$('[data-request-code]');rows.forEach(row=>{const kind=row.dataset.requestKind,order=(serverLists[kind]||[]).find(x=>x.code===row.dataset.requestCode);row.hidden=!!order&&!requestMatches(order,kind);if(!row.hidden)shown++});for(const table of $$('[data-admin-order-table]')){const body=$('tbody',table);if(!body)continue;const sorted=$$('[data-request-code]',body).sort((a,b)=>{const find=row=>(serverLists[row.dataset.requestKind]||[]).find(x=>x.code===row.dataset.requestCode)||{};return compareAdminOrders(find(a),find(b),requestQueueState.sort)});sorted.forEach(row=>body.appendChild(row));const empty=$('[data-order-empty]',table);if(empty)empty.hidden=sorted.some(row=>!row.hidden)}const count=$('#requestQueueCount');if(count)count.textContent=shown?'Найдено заказов: '+shown:'Нет заказов по выбранным фильтрам'}
const requestsBeforeUX=ADM_RENDER.requests;
ADM_RENDER.requests=function(){requestsBeforeUX();const options=(values,current)=>values.map(([id,label])=>`<option value="${esc(id)}" ${current===id?'selected':''}>${esc(label)}</option>`).join(''),cities=[...new Set([...(C.transfer?.to||[]).map(city=>city.name),...C.tours.flatMap(t=>(t.departureCities||[]).map(c=>typeof c==='string'?c:c.name)),...(serverLists.bookings||[]).map(o=>o.city),...(serverLists.transfers||[]).map(o=>o.hotelCity)].filter(Boolean))].sort();$('#admMain .adm-head').insertAdjacentHTML('afterend',`<div class="request-queue-tools compact-order-filters"><label class="field queue-search"><span>Поиск заказа</span><input class="input" id="requestQueueSearch" value="${esc(requestQueueState.query)}" placeholder="Имя, телефон, номер, маршрут"></label><label class="field"><span>Статус</span><select class="input" id="requestQueueStatus">${options([['all','Все статусы'],['active','Активные'],['pending','Новые / на проверке'],['answered','Получены уточнения'],['needs_info','Ждут ответа'],['confirmed','Подтверждены'],['awaiting_payment','Ожидают оплаты'],['paid','В работе'],['rejected','Отклонены'],['completed','Выполнены'],['cancelled','Отменены']],requestQueueState.status)}</select></label><label class="field"><span>Тип заказа</span><select class="input" id="requestQueueKind">${options([['all','Все'],['bookings','Экскурсии'],['transfers','Трансферы']],requestQueueState.kind)}</select></label><label class="field"><span>Сортировка</span><select class="input" id="requestQueueSort">${options([['attention','Требуют внимания'],['newest','Сначала новые'],['dateAsc','Дата: ближайшие'],['dateDesc','Дата: поздние'],['name','Имя: А–Я'],['priceDesc','Сумма: по убыванию'],['priceAsc','Сумма: по возрастанию']],requestQueueState.sort)}</select></label><details class="queue-extra"><summary>Город и период</summary><div><label class="field"><span>Город</span><select class="input" id="requestQueueCity">${options([['all','Все города'],...cities.map(city=>[city,city])],requestQueueState.city)}</select></label><label class="field"><span>Дата от</span><input class="input" id="requestQueueFrom" type="date" value="${esc(requestQueueState.from)}"></label><label class="field"><span>Дата до</span><input class="input" id="requestQueueTo" type="date" value="${esc(requestQueueState.to)}"></label></div></details><div class="queue-result"><span id="requestQueueCount" role="status"></span><button class="linkbtn" type="button" data-reset-order-filters>Сбросить</button></div></div>`);$('#admMain').classList.add('compact-orders-admin');applyRequestQueue()};
document.addEventListener('change',e=>{if(e.target.id==='requestQueueStatus'){requestQueueState.status=e.target.value;applyRequestQueue()}if(e.target.id==='requestQueueKind'){requestQueueState.kind=e.target.value;applyRequestQueue()}});
