function paymentEditorHTML(order){const p=order.payment||{};return `<details class="order-payment-editor"><summary>Счёт от платёжного сервера</summary><p class="hint">Вставьте данные реального счёта. Успешная оплата проверяется сервером.</p><label class="field">ID счёта<input class="input" data-payment-id value="${esc(p.id||'')}" maxlength="100"></label><label class="field">Сумма, ₽<input class="input" data-payment-amount type="number" min="0.01" step="0.01" value="${esc(p.amount||'')}"></label><label class="field">URL QR-кода<input class="input" data-payment-qr type="url" value="${esc(p.qrUrl||'')}"></label><label class="field">Ссылка оплаты<input class="input" data-payment-link type="url" value="${esc(p.paymentUrl||'')}"></label><label class="field">Срок оплаты (МСК)<input class="input" data-payment-expires placeholder="2026-10-13T18:00:00+03:00" value="${esc(p.expiresAt||'')}"></label></details>`}
