document.addEventListener('click',e=>{const preset=e.target.closest('[data-appearance-preset]'),reset=e.target.closest('[data-appearance-reset]');if(!preset&&!reset)return;const draft=appearanceDraft();if(reset)draft[appearanceMode]=appearanceDefault(appearanceMode==='dark');else{const [,a,b]=GLASS_PRESETS[Number(preset.dataset.appearancePreset)]||GLASS_PRESETS[0];draft[appearanceMode]=appearanceNormalize(draft[appearanceMode],appearanceMode==='dark');Object.assign(draft[appearanceMode][appearanceKind],{start:a,end:b,text:parseInt(a.slice(1,3),16)*.299+parseInt(a.slice(3,5),16)*.587+parseInt(a.slice(5,7),16)*.114>165?'#183c50':'#ffffff'})}admSave();redrawAppearanceEditor()});
