ADM_RENDER.fleet=function(){const f=ensureFleetDraft();$('#admMain').innerHTML=`<header class="adm-head"><h1>Автопарк</h1><div class="head-btns"><a class="btn btn-ghost small" href="#/fleet" target="_blank">Открыть каталог</a><button type="button" class="btn btn-sea small" data-fleet-add>Добавить автомобиль</button></div></header>${card('Модели и фотографии',`<p class="hint">Один справочник для всего сайта. Модели и фото из презентации уже добавлены. Примеры не выбираются в заявке: замените название и данные, добавьте фото и выключите «Пример». Номера и назначения диспетчера здесь не задаются.</p><label class="field">Найти карточку<input class="input" data-fleet-admin-search type="search" placeholder="Название или модель"></label><div id="fleetAdminVehicles">${f.vehicles.map(fleetEditorVehicle).join('')}</div>`)}${card('О компании и партнёрам',`${F.text('fleet.company.title','Заголовок')}${F.area('fleet.company.intro','Коротко о компании',2)}${F.area('fleet.company.body','Подробнее',5)}${F.area('fleet.company.partners','Условия сотрудничества',4)}<p class="hint">Информация подготовлена по презентации компании. Тексты редактируются здесь; изменения публикуются кнопкой «Сохранить». Для звонка используются действующие контакты сайта.</p>`)}`;setupCompactAdmin();setupAdminSave()};
const tourEditorBeforeFleet=ADM_RENDER.tour;
ADM_RENDER.tour=function(id){tourEditorBeforeFleet(id);const index=C.tours.findIndex(t=>t.id===id);if(index<0)return;const selected=C.tours[index].vehicleIds||[];$('#admMain').insertAdjacentHTML('beforeend',card('Транспорт на маршруте',`<p class="hint">Если ничего не отмечено — показываются все подходящие экскурсионные автомобили. Для индивидуальной поездки турист может оставить пожелание.</p><div class="adm-flags">${Fleet.vehicles(C,true).filter(v=>v.excursion).map(v=>`<label class="check"><input type="checkbox" data-tour-vehicle="${esc(v.id)}" data-tour-index="${index}" ${selected.includes(v.id)?'checked':''}>${esc(v.name)}${v.hidden?' · скрыт':''}</label>`).join('')||'<a href="#/admin/fleet">Сначала добавьте транспорт</a>'}</div>`));setupCompactAdmin();setupAdminSave()};
let fleetDialog=null;
function openFleetVehicle(id){const v=Fleet.vehicles(C).find(v=>v.id===id);if(!v)return;fleetDialog?.remove();const box=document.createElement('dialog');box.className='tour-banner-dialog fleet-dialog';const photos=(v.photos||[]).map(Fleet.safePhoto).filter(Boolean);box.innerHTML=`<header><h2>${esc(v.name)}</h2><button type="button" class="ibtn" data-fleet-close aria-label="Закрыть">✕</button></header><div class="fleet-photo-strip">${photos.length?photos.map(photo=>`<img src="${esc(photo)}" alt="${esc(v.name)}">`).join(''):fleetPhoto(v)}</div><p>${fleetMeta(v)}</p><p class="hint">${v.example?'Пример типа транспорта. Реальные фото и характеристики будут добавлены.':'Фото модели из презентации компании или каталога. Комплектацию и доступность конкретного автомобиля на дату подтверждает диспетчер.'}</p>`;box.addEventListener('click',e=>{if(e.target===box||e.target.closest('[data-fleet-close]'))box.close()});box.addEventListener('close',()=>{box.remove();if(fleetDialog===box)fleetDialog=null});document.body.append(box);fleetDialog=box;box.showModal()}
document.addEventListener('change',async e=>{const t=e.target;if(t.dataset.fleetFilter){fleetFilters[t.dataset.fleetFilter]=t.value;renderFleetResults()}if(t.dataset.preferredVehicle){const state=t.dataset.preferredVehicle==='bookings'?bk:tr;state.preferredVehicleId=t.value;saveRequestDraft(t.dataset.preferredVehicle)}if(t.dataset.tourVehicle){const tour=C.tours[Number(t.dataset.tourIndex)];if(!C.fleet)ensureFleetDraft();const ids=new Set(tour.vehicleIds||[]);if(t.checked)ids.add(t.dataset.tourVehicle);else ids.delete(t.dataset.tourVehicle);tour.vehicleIds=[...ids];admSave()}if(t.dataset.fleetClass){const v=ensureFleetDraft().vehicles[Number(t.dataset.vehicleIndex)],ids=new Set(v.transferClassIds||[]);if(t.checked)ids.add(t.dataset.fleetClass);else ids.delete(t.dataset.fleetClass);v.transferClassIds=[...ids];admSave()}if(t.dataset.fleetUpload!==undefined){const v=ensureFleetDraft().vehicles[Number(t.dataset.fleetUpload)];if(!v)return;const files=[...t.files].slice(0,12-(v.photos||[]).length);if(!files.length)return;const old=t.disabled;t.disabled=true;try{for(const file of files){if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>15*1024*1024){toast('Фото: JPG, PNG или WebP до 15 МБ');continue}const stored=await storePhoto(file,1600);const url=stored?.startsWith('img:')?mediaMapping[stored.slice(4)]||IMG[stored.slice(4)]:stored;if(!C.fleet?.vehicles.includes(v))return;if(url&&Fleet.safePhoto(url))(v.photos||(v.photos=[])).push(url)}admSave();ADM_RENDER.fleet()}catch(err){toast('Не удалось загрузить фото: '+err.message)}finally{t.disabled=old}}});
document.addEventListener('click',e=>{const view=e.target.closest('[data-fleet-view]');if(view){openFleetVehicle(view.dataset.fleetView);return}if(e.target.closest('[data-fleet-add]')){ensureFleetDraft().vehicles.push({id:'vehicle-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,6),name:'Новый автомобиль',type:'minivan',capacity:null,luggage:null,features:[],photos:[],transfer:true,excursion:true,individual:true,group:true,hidden:false,example:false,transferClassIds:[],_new:true});admSave();ADM_RENDER.fleet();return}const action=e.target.closest('[data-fleet-delete],[data-fleet-up],[data-fleet-photo-up],[data-fleet-photo-delete]');if(!action)return;const f=ensureFleetDraft(),d=action.dataset;if(d.fleetDelete!==undefined){const v=f.vehicles[Number(d.fleetDelete)];if(C.tours.some(t=>(t.vehicleIds||[]).includes(v.id)))return toast('Сначала уберите автомобиль из экскурсий или скройте карточку.');f.vehicles.splice(Number(d.fleetDelete),1)}if(d.fleetUp!==undefined){const i=Number(d.fleetUp);if(i>0)[f.vehicles[i-1],f.vehicles[i]]=[f.vehicles[i],f.vehicles[i-1]]}if(d.fleetPhotoUp!==undefined){const i=Number(d.fleetPhotoUp),v=f.vehicles[Number(d.vehicleIndex)];if(i>0)[v.photos[i-1],v.photos[i]]=[v.photos[i],v.photos[i-1]]}if(d.fleetPhotoDelete!==undefined)f.vehicles[Number(d.vehicleIndex)].photos.splice(Number(d.fleetPhotoDelete),1);admSave();ADM_RENDER.fleet()});
/* 14.6: home settings — photos of the «Куда поехать» categories */
const v4HeroAdminBefore=ADM_RENDER.hero;
ADM_RENDER.hero=function(...a){const r=v4HeroAdminBefore.apply(this,a);const main=$('#admMain');if(!main)return r;const cats=v4HomeCats();C.homeCats=cats.map(c=>({cat:c.cat,title:c.title,photo:c.photo||''}));main.insertAdjacentHTML('beforeend',card('Куда поехать — фото категорий',`<p class="sub">Пейзаж для каждой категории на главной. Лучше горизонтальное фото от 1600 px без надписей. Если фото не загружено, берётся обложка первой экскурсии категории.</p><div class="adm-grid">${C.homeCats.map((c,i)=>`<div>${F.text(`homeCats.${i}.title`,'Название · '+esc(CAT[c.cat]||c.cat))}${F.photo(`homeCats.${i}.photo`,'Фото',['mount',0])}</div>`).join('')}</div><p class="hint">Лента «Чаще всего бронируют» показывает до 8 экскурсий с отметкой «Популярная». Их число меняется в разделе «Популярные».</p>`));if(typeof setupCompactAdmin==='function')setupCompactAdmin();if(typeof setupAdminSave==='function')setupAdminSave();return r};
const v17AdminSiteBefore=ADM_RENDER.site;
ADM_RENDER.site=function(...a){const r=v17AdminSiteBefore.apply(this,a);const main=$('#admMain');if(main&&!$('[data-k="site.vk"]',main)){main.insertAdjacentHTML('beforeend',card('Соцсети в подвале',`<div class="adm-grid">${F.text('site.vk','ВКонтакте — ссылка https://vk.com/…')}${F.text('site.instagram','Instagram — ссылка https://instagram.com/…')}</div><p class="hint">Пока ссылка не указана, значок показывается неактивным и никуда не ведёт.</p>`)+card('Условия и вопросы',`${F.area('site.bookingTerms','Условия бронирования (абзацы через пустую строку; пусто — демонстрационный текст)',8)}${F.area('site.faqText','Частые вопросы: вопрос на первой строке, ответ ниже, блоки через пустую строку (пусто — стандартный список)',10)}`));if(typeof setupCompactAdmin==='function')setupCompactAdmin();if(typeof setupAdminSave==='function')setupAdminSave()}return r};
/* Telegram staff access. Only the owner sees this section; roles are bound to the
   immutable Telegram identity, while names and @usernames are used for search. */
ADM_TABS.push(['staff','Сотрудники']);
adminGroups.find(group=>group[0]==='Система')?.[1].push('staff');
async function refreshStaff(){const root=$('#staffRows');if(root)root.innerHTML='<p class="hint">Загрузка…</p>';try{staffRows=(await api('/api/admin/staff')).staff||[];renderStaffRows()}catch(error){if(root)root.innerHTML=`<p class="err">${esc(error.message)}</p>`}}
ADM_RENDER.staff=function(){$('#admMain').innerHTML=`<header class="adm-head"><div><h1>Сотрудники</h1><p class="sub">Здесь появляются люди, которые хотя бы раз вошли через Telegram.</p></div></header>${card('Доступ к админке',`<label class="field staff-search"><span>Поиск по имени или нику</span><input class="input" type="search" data-staff-search placeholder="Имя или @username" autocomplete="off"></label><p class="hint">Доступ привязан к Telegram ID: смена имени или ника его не сбросит.</p><div id="staffRows" class="staff-list" aria-live="polite"></div>`)}`;refreshStaff()};
const staffRequestsBefore=ADM_RENDER.requests;
ADM_RENDER.requests=function(...args){const result=staffRequestsBefore.apply(this,args);if(serverStaffRole==='observer'){const main=$('#admMain');main?.classList.add('staff-observer');main?.querySelectorAll('.order-admin-tools input,.order-admin-tools select,.order-admin-tools textarea,.order-admin-tools button').forEach(control=>control.disabled=true);main?.querySelector('.adm-head')?.insertAdjacentHTML('beforeend','<p class="hint">Режим наблюдателя · изменение заявок отключено</p>')}return result};
function v152CollectMedia(value,out=new Set(),depth=0){if(depth>8||value==null)return out;if(typeof value==='string'){const u=v152MediaUrl(value);if(u)out.add(u);return out}if(Array.isArray(value)){for(const x of value)v152CollectMedia(x,out,depth+1);return out}if(typeof value==='object')for(const [k,x] of Object.entries(value)){if(k==='mediaLight'||k==='visualEditor')continue;v152CollectMedia(x,out,depth+1)}return out}
// Earlier uploads: light copies are made during a save started by the admin (never on their own).
let v152CompressBusy=false;
async function v152CompressSaved(limit=24){if(v152CompressBusy||serverEditor||typeof document==='undefined'||typeof fetch!=='function')return 0;v152CompressBusy=true;let uploads=0,done=0;
 try{const known=C.mediaLight&&typeof C.mediaLight==='object'?C.mediaLight:{},todo=[...v152CollectMedia(C)].filter(u=>!known[u]&&!Object.values(known).some(x=>x&&(x.t===u||x.f===u)));if(!todo.length)return 0;const light=v152Light();
  for(const url of todo){if(uploads>=limit)break;admStatus?.(`Сжимаем фото: ${done+1} из ${Math.min(todo.length,Math.ceil(limit/2))}…`);
   try{const response=await fetch(url);if(!response.ok)continue;const blob=await response.blob();if(!blob.type.startsWith('image/')||blob.type==='image/svg+xml'){light[url]={skip:1};continue}
    const image=await v152LoadImage(URL.createObjectURL(blob));if(!image){light[url]={skip:1};continue}const big=Math.max(image.width,image.height),entry={};
    if(big>V152_THUMB*1.15){entry.t=await v152Upload(v152Resize(image,V152_THUMB));uploads++}
    const fullData=v152Resize(image,V152_FULL),fullBytes=Math.round((fullData.length-fullData.indexOf(',')-1)*3/4);
    if(fullBytes<blob.size*.8){entry.f=await v152Upload(fullData);uploads++}
    light[url]=Object.keys(entry).length?entry:{skip:1};URL.revokeObjectURL(image.src);done++}catch(err){if(/лимит/i.test(err?.message||''))break}}
 }finally{v152CompressBusy=false}return done}
const saveAdminChangesBeforeV152=saveAdminChanges;
saveAdminChanges=async function(...a){if(!adminSaving&&adminDirty&&serverAdmin&&!serverEditor){try{await v152CompressSaved()}catch{}}return saveAdminChangesBeforeV152.apply(this,a)};
const heroAdminBeforeSeason=ADM_RENDER.hero;
ADM_RENDER.hero=function(...a){const r=heroAdminBeforeSeason.apply(this,a);const main=$('#admMain');if(!main)return r;const normalized=v152Season(),hadSeason=C.seasonBanner&&typeof C.seasonBanner==='object';C.seasonBanner={show:normalized.show,items:normalized.items.map(({mode,tour,url})=>({mode,tour,url}))};
 // Filling in the defaults is not an edit: the saved baseline gets the same values.
 if(adminBaseline&&(!hadSeason||!Array.isArray(adminBaseline.seasonBanner?.items)))adminBaseline.seasonBanner=clone(C.seasonBanner);
 const tours=[['','Все экскурсии (каталог)'],...C.tours.filter(t=>tourPublic(t)).map(t=>[t.id,t.title])];
 const banners=normalized.items.map((item,i)=>`<div class="v152-season-admin"><video muted loop playsinline autoplay poster="${esc(item.poster)}"><source src="${esc(item.webm)}" type="video/webm"><source src="${esc(item.mp4)}" type="video/mp4"></video><div><b>${i+1}. ${esc(item.title)}</b>${F.select(`seasonBanner.items.${i}.mode`,'По нажатию',[["tour","Открыть экскурсию"],["url","Открыть свою ссылку"]])}${F.select(`seasonBanner.items.${i}.tour`,'Экскурсия',tours)}${F.text(`seasonBanner.items.${i}.url`,'Своя ссылка','https://…')}</div></div>`).join('');
 main.insertAdjacentHTML('beforeend',card('Сезонные баннеры',`<p class="sub">Три анимированных баннера меняются каждые 4 секунды. Для каждого выберите экскурсию или укажите свою безопасную ссылку. При пустом значении откроется каталог экскурсий.</p>${F.bool('seasonBanner.show','Показывать сезонные баннеры')}<div class="v152-season-admin-list">${banners}</div>`));
 if(typeof setupCompactAdmin==='function')setupCompactAdmin();if(typeof setupAdminSave==='function')setupAdminSave();return r};
/* Entry points user-app.js uses to reach the admin panel. */
adminApp={
 view:parts=>adminView(parts),
 click:e=>admClick(e),
 input:e=>admInput(e),
 file:input=>admFile(input),
 render:(tab,...args)=>ADM_RENDER[tab](...args),
 tabs:()=>adminCurrentTabs(),
 refreshModeration:()=>refreshModeration(),
 applyRequestQueue:()=>applyRequestQueue(),
 exitDraft:proceed=>exitAdminDraft(proceed)
};
